using namespace kagcuda;

namespace {
#pragma pack(push,1)
struct ModuleCondBin { uint16_t feature_id; uint8_t cmp,res0; int16_t index; uint16_t res1; int32_t value; };
struct ModuleRuleBin { uint8_t n_conditions,res0; uint16_t route_id; ModuleCondBin conditions[4]; };
struct ModuleGenomeBin { uint16_t prefix_step; uint8_t n_rules,res0; ModuleRuleBin rules[8]; };
struct GenomeFileHeader { char magic[8]; uint32_t version,count; };
struct ResultFileHeader { char magic[8]; uint32_t version,genomes,cases; };
struct ResultBin { int32_t own_money,opp_money; uint16_t route_id,flags; };
#pragma pack(pop)
static_assert(sizeof(ModuleCondBin)==12,"cond ABI");static_assert(sizeof(ModuleRuleBin)==52,"rule ABI");static_assert(sizeof(ModuleGenomeBin)==420,"genome ABI");static_assert(sizeof(ResultBin)==12,"result ABI");

struct TapeDesc { int offset=0,length=0; };
struct RouteDesc { uint16_t route_id=0,reserved=0; int offset=0,length=0; };
struct CaseHost { std::string base,opp; int seat=0; uint64_t seed=0; int prefix=72,family=0,protected_flag=0,own_history=0,eligible=1,high_labor=0,carrot=0; int32_t baseline_margin=0; };
struct CaseDev { TapeDesc base,opp; int seat=0; uint64_t seed=0; int prefix=72,family=0,protected_flag=0,own_history=0,eligible=1,high_labor=0,carrot=0; int32_t baseline_margin=0; };
struct PrefixAux { uint8_t high_labor=0, carrot=0; uint16_t reserved=0; };

static std::vector<std::string> split_tab(const std::string&s){std::vector<std::string>o;size_t p=0;while(true){size_t q=s.find('\t',p);o.push_back(s.substr(p,q==std::string::npos?std::string::npos:q-p));if(q==std::string::npos)break;p=q+1;}return o;}
static std::vector<CaseHost> load_cases(const std::string&path){std::ifstream in(path);if(!in)throw std::runtime_error("cannot open cases "+path);std::vector<CaseHost>o;std::string line;while(std::getline(in,line)){if(line.empty()||line[0]=='#')continue;auto z=split_tab(line);if(z.size()!=12)throw std::runtime_error("case TSV needs 12 fields");CaseHost c;c.base=z[0];c.opp=z[1];c.seat=std::stoi(z[2]);c.seed=std::stoull(z[3]);c.prefix=std::stoi(z[4]);c.family=std::stoi(z[5]);c.protected_flag=std::stoi(z[6]);c.own_history=std::stoi(z[7]);c.eligible=std::stoi(z[8]);c.high_labor=std::stoi(z[9]);c.carrot=std::stoi(z[10]);c.baseline_margin=std::stoi(z[11]);if(c.seat<0||c.seat>1||c.prefix<0||c.prefix>=720)o.clear(),throw std::runtime_error("invalid case");o.push_back(c);}if(o.empty())throw std::runtime_error("empty cases");return o;}
static std::vector<std::string> read_list(const std::string&path){std::ifstream in(path);if(!in)throw std::runtime_error("cannot open list "+path);std::vector<std::string>o;std::string x;while(std::getline(in,x)){while(!x.empty()&&(x.back()=='\r'||x.back()==' '||x.back()=='\t'))x.pop_back();size_t p=x.find_first_not_of(" \t");if(p==std::string::npos||x[p]=='#')continue;o.push_back(x.substr(p));}return o;}
static int route_id_from_path(const std::string&p){size_t q=p.rfind("route");if(q==std::string::npos)throw std::runtime_error("route filename missing routeNN: "+p);q+=5;int v=0,n=0;while(q<p.size()&&p[q]>='0'&&p[q]<='9'){v=v*10+(p[q]-'0');++q;++n;}if(!n)throw std::runtime_error("route id parse failed: "+p);return v;}
static std::vector<ModuleGenomeBin> load_genomes(const std::string&path){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("cannot open genomes");GenomeFileHeader h{};in.read((char*)&h,sizeof(h));const char m[8]={'B','4','G','M','1','\0','\0','\0'};if(!in||std::memcmp(h.magic,m,8)||h.version!=1||h.count<1||h.count>100000)throw std::runtime_error("bad genome header");std::vector<ModuleGenomeBin>g(h.count);in.read((char*)g.data(),g.size()*sizeof(g[0]));char extra;if(!in||in.read(&extra,1))throw std::runtime_error("bad genome payload");return g;}
template<class T>static T* copy_dev(const std::vector<T>&v){if(v.empty())return nullptr;T*d=nullptr;KAGCUDA_CHECK(cudaMalloc((void**)&d,v.size()*sizeof(T)));KAGCUDA_CHECK(cudaMemcpy(d,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));return d;}

__device__ __forceinline__ const Action& tape_at(const Action*a,TapeDesc d,int step){int i=step<d.length?step:d.length-1;return a[d.offset+i];}
__device__ __forceinline__ bool cmp32(int32_t a,int32_t b,uint8_t c){switch(c){case bonsaikg::C_EQ:return a==b;case bonsaikg::C_NE:return a!=b;case bonsaikg::C_LE:return a<=b;case bonsaikg::C_GE:return a>=b;default:return false;}}
__device__ __forceinline__ uint16_t choose_route(const ModuleGenomeBin&g,const ObservationView&o){if(o.step()!=g.prefix_step)return 0xffffu;bonsaikg::CudaObservation legal(o);int nr=g.n_rules>8?8:g.n_rules;for(int r=0;r<nr;++r){const auto&rule=g.rules[r];int nc=rule.n_conditions;if(nc<1||nc>4)continue;bool ok=true;for(int k=0;k<nc;++k){const auto&c=rule.conditions[k];if(!cmp32(legal.feature(c.feature_id,c.index,0),c.value,c.cmp)){ok=false;break;}}if(ok)return rule.route_id;}return 0xffffu;}
__device__ __forceinline__ const RouteDesc* find_route(const RouteDesc*r,int n,uint16_t id){for(int i=0;i<n;++i)if(r[i].route_id==id)return r+i;return nullptr;}

__global__ void make_snapshots(Config cfg0,DeviceTables tables,const Action*case_actions,const CaseDev*cases,int n,Sim*sims,Snapshot*snaps,PrefixAux*aux){int ci=blockIdx.x*blockDim.x+threadIdx.x;if(ci>=n)return;const CaseDev c=cases[ci];Config cfg=cfg0;cfg.seed=c.seed;Sim&sim=sims[ci];sim.init(cfg,&tables);bonsaikg_v6::CudaEngineExploitState ex{};for(int t=0;t<c.prefix;++t){Action ca=tape_at(case_actions,c.base,t),oa=tape_at(case_actions,c.opp,t);Action probe=ca;ObservationView obs=make_observation(sim,c.seat);bonsaikg_v6::apply_cuda_engine_exploits(obs,probe,ex,c.eligible!=0,100);int u0=sim.st.farms[0].n_units,u1=sim.st.farms[1].n_units;if(c.seat==0)sim.step_with_unit_counts(ca,u0,oa,u1);else sim.step_with_unit_counts(oa,u0,ca,u1);}sim.save_snapshot(snaps+ci);aux[ci].high_labor=(uint8_t)ex.high_labor;aux[ci].carrot=(uint8_t)ex.carrot_latched;}

__global__ void evaluate(DeviceTables tables,const Snapshot*snaps,const PrefixAux*aux,const Action*case_actions,const CaseDev*cases,int ncases,const Action*route_actions,const RouteDesc*routes,int nroutes,const ModuleGenomeBin*genomes,int ngenomes,Sim*sims,ResultBin*out){int job=blockIdx.x*blockDim.x+threadIdx.x,total=ncases*ngenomes;if(job>=total)return;int gi=job/ncases,ci=job-gi*ncases;const CaseDev c=cases[ci];Sim&sim=sims[job];sim.load_snapshot(snaps[ci],&tables);uint16_t selected=0xffffu;uint16_t flags=0;bonsaikg_v6::CudaEngineExploitState ex{};ex.high_labor=aux[ci].high_labor!=0;ex.carrot_latched=aux[ci].carrot!=0;if(c.eligible){ObservationView o=make_observation(sim,c.seat);selected=choose_route(genomes[gi],o);if(selected!=0xffffu&&!find_route(routes,nroutes,selected)){flags|=2;selected=0xffffu;}}
    while(!sim.st.done){int t=sim.st.step;Action ca{};if(selected==0xffffu){ca=tape_at(case_actions,c.base,t);}else{const RouteDesc*rd=find_route(routes,nroutes,selected);ca=tape_at(route_actions,{rd->offset,rd->length},t);ObservationView o=make_observation(sim,c.seat);bonsaikg_v6::apply_cuda_engine_exploits(o,ca,ex,true,100);}Action oa=tape_at(case_actions,c.opp,t);int u0=sim.st.farms[0].n_units,u1=sim.st.farms[1].n_units;if(c.seat==0)sim.step_with_unit_counts(ca,u0,oa,u1);else sim.step_with_unit_counts(oa,u0,ca,u1);}
    ResultBin r{};r.own_money=(int32_t)sim.st.farms[c.seat].money;r.opp_money=(int32_t)sim.st.farms[1-c.seat].money;r.route_id=selected;r.flags=flags;out[job]=r;
}

static void write_results(const std::string&path,const std::vector<ResultBin>&r,int ng,int nc){std::ofstream out(path,std::ios::binary);if(!out)throw std::runtime_error("cannot write results");ResultFileHeader h{{'B','4','R','S','1','\0','\0','\0'},1u,(uint32_t)ng,(uint32_t)nc};out.write((char*)&h,sizeof(h));out.write((char*)r.data(),r.size()*sizeof(r[0]));}
}

int main(int argc,char**argv){try{std::string cases_path,route_list,genome_path,out_path;int tpb=64;for(int i=1;i<argc;++i){std::string a=argv[i];auto need=[&](){if(i+1>=argc)throw std::runtime_error("missing "+a);return std::string(argv[++i]);};if(a=="--cases")cases_path=need();else if(a=="--routes")route_list=need();else if(a=="--genomes")genome_path=need();else if(a=="--out")out_path=need();else if(a=="--tpb")tpb=std::stoi(need());else throw std::runtime_error("unknown arg "+a);}if(cases_path.empty()||route_list.empty()||genome_path.empty()||out_path.empty())throw std::runtime_error("required --cases --routes --genomes --out");auto hc=load_cases(cases_path);auto hg=load_genomes(genome_path);std::vector<Action>case_actions;std::vector<CaseDev>hcd;for(const auto&c:hc){NativeTape b=load_native_tape_json(c.base),o=load_native_tape_json(c.opp);TapeDesc bd{(int)case_actions.size(),(int)b.actions.size()};case_actions.insert(case_actions.end(),b.actions.begin(),b.actions.end());TapeDesc od{(int)case_actions.size(),(int)o.actions.size()};case_actions.insert(case_actions.end(),o.actions.begin(),o.actions.end());hcd.push_back({bd,od,c.seat,c.seed,c.prefix,c.family,c.protected_flag,c.own_history,c.eligible,c.high_labor,c.carrot,c.baseline_margin});}
    std::vector<Action>route_actions;std::vector<RouteDesc>hrd;std::string list_dir=route_list.substr(0,route_list.find_last_of("/\\"));if(list_dir.empty())list_dir=".";for(auto rel:read_list(route_list)){std::string p=rel.size()&&rel[0]=='/'?rel:list_dir+"/"+rel;NativeTape t=load_native_tape_json(p);RouteDesc d{};d.route_id=(uint16_t)route_id_from_path(p);d.offset=(int)route_actions.size();d.length=(int)t.actions.size();route_actions.insert(route_actions.end(),t.actions.begin(),t.actions.end());hrd.push_back(d);}if(hrd.empty())throw std::runtime_error("empty routes");
    configure_device();TablesOwner tables;Config cfg;cfg.episode_steps=720;Action*dca=copy_dev(case_actions),*dra=copy_dev(route_actions);CaseDev*dc=copy_dev(hcd);RouteDesc*dr=copy_dev(hrd);ModuleGenomeBin*dg=copy_dev(hg);Snapshot*dsnap=nullptr;PrefixAux*daux=nullptr;Sim*dprefix=nullptr,*dbranch=nullptr;ResultBin*dout=nullptr;size_t jobs=(size_t)hc.size()*hg.size();KAGCUDA_CHECK(cudaMalloc((void**)&dsnap,hc.size()*sizeof(Snapshot)));KAGCUDA_CHECK(cudaMalloc((void**)&daux,hc.size()*sizeof(PrefixAux)));KAGCUDA_CHECK(cudaMalloc((void**)&dprefix,hc.size()*sizeof(Sim)));KAGCUDA_CHECK(cudaMalloc((void**)&dbranch,jobs*sizeof(Sim)));KAGCUDA_CHECK(cudaMalloc((void**)&dout,jobs*sizeof(ResultBin)));make_snapshots<<<(hc.size()+63)/64,64>>>(cfg,tables.dev,dca,dc,(int)hc.size(),dprefix,dsnap,daux);KAGCUDA_CHECK(cudaGetLastError());KAGCUDA_CHECK(cudaDeviceSynchronize());cudaEvent_t a,b;KAGCUDA_CHECK(cudaEventCreate(&a));KAGCUDA_CHECK(cudaEventCreate(&b));KAGCUDA_CHECK(cudaEventRecord(a));evaluate<<<(jobs+tpb-1)/tpb,tpb>>>(tables.dev,dsnap,daux,dca,dc,(int)hc.size(),dra,dr,(int)hrd.size(),dg,(int)hg.size(),dbranch,dout);KAGCUDA_CHECK(cudaGetLastError());KAGCUDA_CHECK(cudaEventRecord(b));KAGCUDA_CHECK(cudaEventSynchronize(b));float ms=0;KAGCUDA_CHECK(cudaEventElapsedTime(&ms,a,b));std::vector<ResultBin>h(jobs);KAGCUDA_CHECK(cudaMemcpy(h.data(),dout,jobs*sizeof(ResultBin),cudaMemcpyDeviceToHost));write_results(out_path,h,(int)hg.size(),(int)hc.size());std::cout<<"genomes="<<hg.size()<<" cases="<<hc.size()<<" games="<<jobs<<" gpu_ms="<<ms<<" games_s="<<(jobs/(ms/1000.0))<<" sim_bytes="<<sizeof(Sim)<<" snapshot_bytes="<<sizeof(Snapshot)<<" branch_MiB="<<(jobs*sizeof(Sim)/(1024.0*1024.0))<<"\n";cudaFree(dca);cudaFree(dra);cudaFree(dc);cudaFree(dr);cudaFree(dg);cudaFree(dsnap);cudaFree(daux);cudaFree(dprefix);cudaFree(dbranch);cudaFree(dout);cudaEventDestroy(a);cudaEventDestroy(b);return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
